Array.prototype.myForEach = function (callback, thisArg) {
  for (let i = 0; i < this.length; i++) {
    if (i in this) callback.call(thisArg, this[i], i);
  }
};

const shelf = { label: "Shelf" };
const books = ["Dune", , undefined, "Emma"];

books.myForEach(function (book, i) {
  console.log(`${this.label} ${i}: ${book}`);
}, shelf);
